COMMAND_IDS_BY_NAME: Dict[str, Tuple[int, ...]] = {}
for _cmd_id, _cmd in COMMANDS.items():
    COMMAND_IDS_BY_NAME.setdefault(_cmd.name, ())
    COMMAND_IDS_BY_NAME[_cmd.name] = COMMAND_IDS_BY_NAME[_cmd.name] + (_cmd_id,)


def get_command(cmd_id: int) -> CommandDef | None:
    return COMMANDS.get(cmd_id)


def get_value_type(type_code: int) -> ValueTypeDef | None:
    return VALUE_TYPES.get(type_code & 0xFFFF)


def signed_i16_to_u16(value: int) -> int:
    return value & 0xFFFF
